import (
    "encoding/csv"
    "os"
)

func ReadCsv(filename string) ([][]string, error) {
    f, err := os.Open(filename)
    if err != nil {
        return nil, err
    }
    defer f.Close()
    r := csv.NewReader(f)
    r.FieldsPerRecord = -1 // allow ragged rows
    return r.ReadAll()
}

