import (
    "encoding/csv"
    "os"
)

func WriteCsv(filename string, headers []string, rows [][]string) error {
    f, err := os.Create(filename)
    if err != nil {
        return err
    }
    defer f.Close()
    w := csv.NewWriter(f)
    if err := w.Write(headers); err != nil {
        return err
    }
    if err := w.WriteAll(rows); err != nil {
        return err
    }
    w.Flush()
    return w.Error()
}

